css:
/* Certificate of completion — landscape A4, rendered by wkhtmltopdf.
 *
 * wkhtmltopdf runs an old WebKit: no flexbox, no CSS grid, no calc(), no custom
 * properties, and CSS transforms are unreliable. Layout below is box-model and
 * absolute positioning in centimetres, with one table for the footer row.
 * Artwork is inline SVG made of flat fills only: this WebKit ignores SVG group
 * opacity, so tints are plain colours.
 *
 * The page is two fields. The sheet on the left carries what the certificate
 * says: who, for what, when, by whom. The panel on the right carries what makes
 * it a credential: the issuer's medal, and a QR code that opens the public
 * verification page for this certificate ID. One typeface, a lot of white, and
 * shapes rather than ornament.
 */

/* Frappe reads these from the .print-format rule and passes them to
   wkhtmltopdf. The <meta name="pdfkit-orientation"> tag this format used to
   rely on is not honoured on this path: the certificate came out portrait,
   inside 15mm margins, with the title wrapped. */
.print-format {
    orientation: Landscape;
    page-size: A4;
    margin-top: 0mm;
    margin-bottom: 0mm;
    margin-left: 0mm;
    margin-right: 0mm;
    padding: 0 !important;
    margin: 0 !important;
    max-width: none !important;
    width: 29.8cm;
    min-height: 0 !important;
}

/* wkhtmltopdf lays a centimetre out a fraction short, which left a hairline of
   bare paper down the right edge. The panel runs 1mm past that edge, where the
   page clips it. The height cannot take the same fix: 0.2mm over 21cm and the
   overflow becomes a second, empty page. */
.cert {
    position: relative;
    width: 29.8cm;
    height: 21cm;
    overflow: hidden;
    background-color: #FFFFFF;
    font-family: "Geist", "Inter", "Helvetica Neue", "Liberation Sans", "DejaVu Sans", sans-serif;
    color: #16202E;
    -webkit-print-color-adjust: exact;
}

/* Every class is prefixed. Frappe's print stylesheet ships Bootstrap, whose
   .panel, .label and .lead rules restyle anything sharing those names: the
   panel picked up Bootstrap's border and rounded corners that way. */

/* ------------------------------------------------------------------- sheet */
.cert-sheet {
    position: absolute;
    left: 0;
    top: 0;
    width: 22.3cm;
    height: 21cm;
    overflow: hidden;
    background-color: #FFFFFF;
}

/* Quarter circles stepping into the panel from the sheet's top-right corner. */
.cert-corner-art {
    position: absolute;
    left: 16.3cm;
    top: 0;
    width: 6cm;
    height: 6cm;
}

/* The brand colour, once, down the binding edge. */
.cert-edge {
    position: absolute;
    left: 0;
    top: 0;
    width: 0.32cm;
    height: 21cm;
    background-color: #00A2F3;
}

.cert-brand { position: absolute; left: 2.3cm; top: 1.9cm; }
.cert-brand-logo { height: 0.85cm; vertical-align: middle; }
/* Explicit width: with only a height, wkhtmltopdf lays an inline <svg> out
   zero pixels wide and the wordmark silently disappears. */
.cert-brand-wordmark { width: 3.6cm; height: 0.75cm; }
.cert-brand-name {
    display: inline-block;
    vertical-align: middle;
    margin-left: 8px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

.cert-main {
    position: absolute;
    left: 2.3cm;
    top: 5.6cm;
    width: 17.6cm;
}

.cert-eyebrow {
    display: inline-block;
    padding: 6px 13px;
    border-radius: 999px;
    background-color: #EAF6FE;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    white-space: nowrap;
    color: #0784C4;
    margin-bottom: 0.95cm;
}

.cert-lede {
    font-size: 15px;
    color: #5A6B80;
    margin-bottom: 0.2cm;
}

/* The recipient is the hero. Long names step down rather than overflow. */
.cert-name {
    font-weight: 600;
    font-size: 56px;
    line-height: 1.08;
    letter-spacing: -0.025em;
    color: #16202E;
}
.cert-name-sm { font-size: 44px; }
.cert-name-xs { font-size: 34px; }

.cert-name-rule {
    width: 2.2cm;
    height: 4px;
    margin: 0.55cm 0 0.65cm;
    background-color: #00A2F3;
}

.cert-body {
    font-size: 15px;
    color: #5A6B80;
    margin-bottom: 0.25cm;
}

.cert-award {
    font-weight: 600;
    font-size: 27px;
    line-height: 1.22;
    letter-spacing: -0.012em;
    color: #16202E;
    max-width: 16.6cm;
}
.cert-award-sm { font-size: 22px; }
.cert-award-xs { font-size: 18px; }

.cert-note {
    margin-top: 0.4cm;
    font-size: 12.5px;
    color: #7B8CA1;
}
.cert-note-sep { padding: 0 0.15cm; }

/* ------------------------------------------------------------------ footer */
/* The wrapper is what is positioned, not the table: an absolutely positioned
   <table> shrink-wraps its content in WebKit and ignores left + right. */
.cert-foot {
    position: absolute;
    left: 2.3cm;
    top: 16.6cm;
    width: 17.6cm;
    padding-top: 0.55cm;
    border-top: 1px solid #E1E8F0;
}

.cert-foot-table { width: 100%; border-collapse: collapse; table-layout: fixed; }

/* !important: Frappe's print stylesheet pads every table cell in a print
   format, which pushed this row out of line with the text above it. */
.cert-foot-table td {
    width: 33.33%;
    vertical-align: top;
    padding: 0 0.8cm 0 0 !important;
    border: 0 !important;
    text-align: left;
}

.cert-foot-label {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #8496AB;
    margin-bottom: 6px;
}

.cert-foot-value {
    font-size: 14px;
    font-weight: 600;
    line-height: 20px;
    color: #16202E;
}

.cert-foot-id {
    font-family: "SFMono-Regular", "Menlo", "DejaVu Sans Mono", "Liberation Mono", monospace;
    font-size: 13px;
    font-weight: 400;
    letter-spacing: 0.04em;
}

.cert-foot-sub { margin-top: 3px; font-size: 10px; color: #8496AB; }

/* ------------------------------------------------------------------- panel */
.cert-panel {
    position: absolute;
    left: 22.3cm;
    top: 0;
    width: 7.5cm;
    height: 21cm;
    overflow: hidden;
    background-color: #16202E;
    text-align: center;
}

.cert-panel-art {
    position: absolute;
    left: 0;
    top: 0;
    width: 7.5cm;
    height: 21cm;
}

.cert-panel-caption {
    position: absolute;
    left: 0;
    top: 10.2cm;
    width: 7.4cm;
    font-size: 10.5px;
    font-weight: 600;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: #FFFFFF;
}

.cert-qr-block { position: absolute; left: 0; top: 13.3cm; width: 7.4cm; }

.cert-qr-label {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.26em;
    text-transform: uppercase;
    color: #9FB2C8;
    margin-bottom: 0.3cm;
}

/* The white card is the code's quiet zone as well as its frame. */
.cert-qr-card {
    box-sizing: border-box;
    -webkit-box-sizing: border-box;
    width: 3.9cm;
    height: 3.9cm;
    margin: 0 auto;
    padding: 0.4cm;
    background-color: #FFFFFF;
    border-radius: 0.3cm;
}

.cert-qr { display: block; width: 3.1cm; height: 3.1cm; }

.cert-qr-url {
    margin-top: 0.32cm;
    padding: 0 0.5cm;
    font-family: "SFMono-Regular", "Menlo", "DejaVu Sans Mono", "Liberation Mono", monospace;
    font-size: 8.5px;
    line-height: 1.5;
    letter-spacing: 0.02em;
    color: #9FB2C8;
    word-wrap: break-word;
}

html:
{% set member_name = frappe.db.get_value("User", doc.member, "full_name") or doc.member_name %}
{% set course_title = frappe.db.get_value("LMS Course", doc.course, "title") if doc.course else None %}
{% set award_title = course_title or doc.batch_title %}
{% set logo = frappe.db.get_single_value("Website Settings", "banner_image") %}
{% set brand_name = frappe.db.get_single_value("Website Settings", "app_name") %}
{% set instructors = frappe.get_all("Course Instructor", {"parent": doc.course}, pluck="instructor", order_by="idx") if doc.course else [] %}
{% set verify_url = frappe.utils.get_url("/verify/" ~ doc.name) %}
{% set qr = get_qr_code_path(verify_url) %}

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap" rel="stylesheet">

<div class="cert">
	<div class="cert-sheet">
		<svg class="cert-corner-art" viewBox="0 0 600 600" xmlns="http://www.w3.org/2000/svg"><circle cx="600" cy="0" r="560" fill="#EAF6FE"/><circle cx="600" cy="0" r="340" fill="#D3ECFD"/><circle cx="170" cy="150" r="26" fill="#F0C566"/></svg>
		<span class="cert-edge"></span>

		<div class="cert-brand">
			{% if logo %}
				<img src="{{ logo }}" class="cert-brand-logo">
				<span class="cert-brand-name">{{ brand_name }}</span>
			{% else %}
				<svg class="cert-brand-wordmark" viewBox="0 33 517 108" xmlns="http://www.w3.org/2000/svg"><path d="M130.516 35.8742V99.9947C130.516 111.885 137.028 118.891 148.564 118.891C160.1 118.891 166.54 111.885 166.54 99.9947V35.8742H192.514V102.755C192.514 125.685 175.104 140.76 148.564 140.76C122.024 140.76 104.543 125.685 104.543 102.755V35.8742H130.516ZM266.472 138H240.569V56.7523H211.127V35.8742H295.984V56.7523H266.472V138ZM310.068 108.912H334.839C335.476 116.343 342.907 121.085 353.665 121.085C363.361 121.085 370.013 116.414 370.013 109.691C370.013 104.029 365.555 100.986 353.877 98.6501L340.43 95.9607C321.746 92.422 312.121 82.2307 312.121 66.1651C312.121 46.2071 328.115 33.114 352.745 33.114C376.666 33.114 393.227 46.0655 393.652 64.962H369.659C369.093 57.7431 362.228 52.7182 353.098 52.7182C343.969 52.7182 337.953 57.0354 337.953 63.8296C337.953 69.4207 342.482 72.6763 353.24 74.7995L366.404 77.3473C386.574 81.2398 395.633 90.3696 395.633 106.577C395.633 127.879 379.355 140.76 352.603 140.76C326.771 140.76 310.493 128.587 310.068 108.912ZM441.353 35.8742V99.9947C441.353 111.885 447.864 118.891 459.4 118.891C470.936 118.891 477.376 111.885 477.376 99.9947V35.8742H503.35V102.755C503.35 125.685 485.94 140.76 459.4 140.76C432.86 140.76 415.379 125.685 415.379 102.755V35.8742H441.353Z" fill="#16202E"/><path d="M0 57.627V35.8418H83.0678V99.303C83.0678 122.984 63.7154 140.842 41.2971 140.842C17.7083 140.842 0 121.148 0 99.303V83.3903H21.7852V99.303C21.7852 111.003 31.588 119.054 41.2971 119.054C52.4085 119.054 61.2827 110.326 61.2827 99.303V57.627H0Z" fill="#16202E"/><path d="M10.8919 77.8967C14.9199 77.8967 18.1852 74.6313 18.1852 70.6034C18.1852 66.5754 14.9199 63.3101 10.8919 63.3101C6.86395 63.3101 3.59863 66.5754 3.59863 70.6034C3.59863 74.6313 6.86395 77.8967 10.8919 77.8967Z" fill="#00A2F3"/></svg>
			{% endif %}
		</div>

		<div class="cert-main">
			<div class="cert-eyebrow">{{ _("Certificate of Completion") }}</div>

			<div class="cert-lede">{{ _("This is to certify that") }}</div>

			<div class="cert-name{% if member_name|length > 34 %} cert-name-xs{% elif member_name|length > 24 %} cert-name-sm{% endif %}">{{ member_name }}</div>
			<div class="cert-name-rule"></div>

			<div class="cert-body">
				{% if course_title %}
					{{ _("has successfully completed the course") }}
				{% else %}
					{{ _("has successfully completed the batch") }}
				{% endif %}
			</div>

			<div class="cert-award{% if award_title and award_title|length > 92 %} cert-award-xs{% elif award_title and award_title|length > 46 %} cert-award-sm{% endif %}">{{ award_title }}</div>

			<div class="cert-note">
				{{ _("including all required assessments.") }}
				{% if doc.batch_title and course_title %}
					<span class="cert-note-sep">&middot;</span> {{ _("Batch") }}: {{ doc.batch_title }}
				{% endif %}
			</div>
		</div>

		<div class="cert-foot">
			<table class="cert-foot-table">
				<tr>
					<td>
						<div class="cert-foot-label">{{ _("Issued On") }}</div>
						<div class="cert-foot-value">{{ frappe.utils.format_date(doc.issue_date, "long") }}</div>
						{% if doc.expiry_date %}
						<div class="cert-foot-sub">
							{{ _("Valid until") }} {{ frappe.utils.format_date(doc.expiry_date, "long") }}
						</div>
						{% endif %}
					</td>
					<td>
						<div class="cert-foot-label">
							{% if doc.evaluator %}
								{{ _("Evaluated By") }}
							{% else %}
								{{ _("Instructor") if instructors|length == 1 else _("Instructors") }}
							{% endif %}
						</div>
						<div class="cert-foot-value">
							{% if doc.evaluator %}
								{{ doc.evaluator_name }}
							{% else %}
								{% for instructor in instructors %}{{ frappe.db.get_value("User", instructor, "full_name") }}{% if not loop.last %}, {% endif %}{% endfor %}
							{% endif %}
						</div>
					</td>
					<td>
						<div class="cert-foot-label">{{ _("Certificate ID") }}</div>
						<div class="cert-foot-value cert-foot-id">{{ doc.name }}</div>
					</td>
				</tr>
			</table>
		</div>

	</div>

	<div class="cert-panel">
		<svg class="cert-panel-art" viewBox="0 0 750 2100" xmlns="http://www.w3.org/2000/svg"><rect width="750" height="2100" fill="#16202E"/><circle cx="750" cy="0" r="560" fill="#1C2A3D"/><circle cx="750" cy="0" r="300" fill="#22344B"/><circle cx="0" cy="2100" r="430" fill="#1C2A3D"/><path d="M292 702.4H362V928L327.0 894L292 928Z" fill="#0784C4"/><path d="M378 702.4H448V928L413.0 894L378 928Z" fill="#00A2F3"/><circle cx="370" cy="610" r="168" fill="#F0C566"/><circle cx="370" cy="610" r="156" fill="#16202E"/><circle cx="370" cy="610" r="144" fill="#00A2F3"/><g transform="translate(318.0 544.3) scale(1.252) translate(0 -35.84)"><path d="M0 57.627V35.8418H83.0678V99.303C83.0678 122.984 63.7154 140.842 41.2971 140.842C17.7083 140.842 0 121.148 0 99.303V83.3903H21.7852V99.303C21.7852 111.003 31.588 119.054 41.2971 119.054C52.4085 119.054 61.2827 110.326 61.2827 99.303V57.627H0Z" fill="#FFFFFF"/><path d="M10.8919 77.8967C14.9199 77.8967 18.1852 74.6313 18.1852 70.6034C18.1852 66.5754 14.9199 63.3101 10.8919 63.3101C6.86395 63.3101 3.59863 66.5754 3.59863 70.6034C3.59863 74.6313 6.86395 77.8967 10.8919 77.8967Z" fill="#FFD37C"/></g></svg>
		<div class="cert-panel-caption">{{ _("Verified Credential") }}</div>

		<div class="cert-qr-block">
			<div class="cert-qr-label">{{ _("Scan to verify") }}</div>
			<div class="cert-qr-card">
				<svg class="cert-qr" viewBox="0 0 {{ qr.size }} {{ qr.size }}" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg"><path d="{{ qr.path }}" fill="#16202E"/></svg>
			</div>
			<div class="cert-qr-url">{{ verify_url | replace("https://", "") | replace("http://", "") }}</div>
		</div>
	</div>
</div>
